INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_T1Z_CIV','T1 - The ZOFGK Dynasty');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_T1Z_CIV5_HEADING_1','Five Legends. One Dynasty.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_T1Z_CIV5_TEXT_1','T1 is a Korean esports organization with a legacy rooted in SK Telecom T1. This civilization commemorates the historical ZOFGK lineup: Choi "Zeus" Woo-je (top), Moon "Oner" Hyeon-joon (jungle), Lee "Faker" Sang-hyeok (mid), Lee "Gumayusi" Min-hyeong (ADC) and Ryu "Keria" Min-seok (support).[NEWLINE][NEWLINE]After reaching the 2022 World Championship final and losing a five-game series to DRX, the five returned to win the 2023 title in Seoul against Weibo Gaming. In 2024 they defended the title in London, defeating Bilibili Gaming in another five-game final. The 2023 and 2024 victories became a defining chapter in the organization''s history. This is a tribute to that historical roster, not a statement about the current team.[NEWLINE][NEWLINE]Five Legends, One Dynasty. The first five Recruits gain roles in Z-O-F-G-K order, including the starting Warrior replacement. Each role survives genuine upgrades. Three or four distinct roles within two hexes grant +10% Strength; all five grant +15% instead. Only roster units benefit. Normal units never count toward the formation.[NEWLINE][NEWLINE]Legendary Development adds +4% permanent Strength per real Recruit upgrade, alongside Scouted Talent''s +15% combat XP. Level-ups and promotion choices add no development. Death erases that individual''s XP and history. Lost roles wait 7/10/15/30 turns on Quick/Standard/Epic/Marathon, then go to the next newly produced non-ranged land military unit in a city with a real Headquarters. Purchased units can join the initial Recruit roster, but cannot fill a replacement vacancy. Gifts and captures cannot recruit. A successor receives only its role, never the deceased''s history.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_T1Z_CIV_PEDIA','T1 is a Korean esports organization with a legacy rooted in SK Telecom T1. This civilization commemorates the historical ZOFGK lineup: Choi "Zeus" Woo-je (top), Moon "Oner" Hyeon-joon (jungle), Lee "Faker" Sang-hyeok (mid), Lee "Gumayusi" Min-hyeong (ADC) and Ryu "Keria" Min-seok (support).[NEWLINE][NEWLINE]After reaching the 2022 World Championship final and losing a five-game series to DRX, the five returned to win the 2023 title in Seoul against Weibo Gaming. In 2024 they defended the title in London, defeating Bilibili Gaming in another five-game final. The 2023 and 2024 victories became a defining chapter in the organization''s history. This is a tribute to that historical roster, not a statement about the current team.[NEWLINE][NEWLINE]Five Legends, One Dynasty. The first five Recruits gain roles in Z-O-F-G-K order, including the starting Warrior replacement. Each role survives genuine upgrades. Three or four distinct roles within two hexes grant +10% Strength; all five grant +15% instead. Only roster units benefit. Normal units never count toward the formation.[NEWLINE][NEWLINE]Legendary Development adds +4% permanent Strength per real Recruit upgrade, alongside Scouted Talent''s +15% combat XP. Level-ups and promotion choices add no development. Death erases that individual''s XP and history. Lost roles wait 7/10/15/30 turns on Quick/Standard/Epic/Marathon, then go to the next newly produced non-ranged land military unit in a city with a real Headquarters. Purchased units can join the initial Recruit roster, but cannot fill a replacement vacancy. Gifts and captures cannot recruit. A successor receives only its role, never the deceased''s history.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_T1Z_CLOSE','Close');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_T1Z_DAWN','Faker, the Unkillable Demon King, you stand at the heart of a dynasty that transformed five extraordinary individuals into legends. Under your leadership, Zeus, Oner, Gumayusi and Keria rose together, challenging the world''s greatest and claiming victories that echoed across generations. Your strength was never merely the brilliance of one player, but the trust, discipline and unity of an unforgettable roster.[NEWLINE][NEWLINE]From the 2022 final to back-to-back World Championships in 2023 and 2024, your team forged a legacy through practice and perseverance.[NEWLINE][NEWLINE]Will you discover a new generation of champions, preserve their legacy through the ages, and lead T1 to victory once more?');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_T1Z_DEFEAT_1','Today belongs to you. We will remember what this team achieved together.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_T1Z_DEVELOPMENT_1','Legendary Development - +4%');
