INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_T1Z_DEVELOPMENT_100_HELP','+400% permanent Strength from 100 genuine Recruit upgrades. Exactly +4% per real unit-type upgrade; no reward from level-ups or promotion choices. This is one exclusive cumulative tier, not an additional stacking award. Retained through upgrades.');
