INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_T1Z_FAKER','Faker - Unkillable Demon King');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_T1Z_FAKER_HEADING_1','Trust, Discipline and Legacy');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_T1Z_FAKER_HELP','Hostile military units within one hex suffer -10% Strength. Does not stack with another Faker aura. Civilians, friends and neutrals are unaffected. Permanent ZOFGK role: leadership, control and clutch decisions.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_T1Z_FAKER_LIVED','Born 1996; tribute to the 2022-2024 ZOFGK era');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_T1Z_FAKER_NAME','Faker');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_T1Z_FAKER_SUBTITLE','The Unkillable Demon King');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_T1Z_FAKER_TEXT_1','Lee "Faker" Sang-hyeok became the central figure of SK Telecom T1''s League of Legends legacy after his professional debut in 2013. Celebrated for mechanical precision, leadership, adaptability and calm under pressure, he became known as the Unkillable Demon King.[NEWLINE][NEWLINE]This tribute focuses on the ZOFGK era. Faker led a roster of developing stars through the heartbreak of the 2022 Worlds final, the 2023 championship in Seoul and a successful title defense in London in 2024. His civilization celebrates the trust and discipline of a team, not invulnerability: preserving veterans and training successors remain essential.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_T1Z_FAKER_TITLES_1','Mid Laner and Team Leader');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_T1Z_FRIENDLY_1','Welcome. A strong teammate is someone you can trust under pressure.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_T1Z_GREETING_1','I am Faker. Five players, one purpose. Let us see what we can build together.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_T1Z_GUMAYUSI','Gumayusi - Unshakeable Carry');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_T1Z_GUMAYUSI_HELP','+15% Strength when attacking wounded enemy military units. Uses damage before combat, with current maximum HP. No bonus against cities, full-health targets or while defending. Permanent ZOFGK role: precision and finishing teamfights.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_T1Z_HOSTILE_1','Your movements have not gone unnoticed.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_T1Z_HQ','T1 Headquarters');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_T1Z_HQ_HELP','Replaces Barracks and retains all active Barracks properties and training experience. Adds +1 [ICON_CULTURE] Culture and +10% local Production toward land melee military units, excluding ranged and defensive-only units. Enables successor recruitment after a roster vacancy cooldown; only newly produced units qualify, not purchases, captures or gifts.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_T1Z_HQ_PEDIA','Headquarters represent the academy, practice rooms, coaching staff and infrastructure behind a championship roster. Visible brilliance rests on years of preparation. This Barracks replacement supports local military training and Culture; it never creates a free successor.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_T1Z_HQ_STRATEGY','Build Headquarters before you need a replacement. Its Production modifier applies to the city training the unit and follows normal queue and overflow rules. The first eligible unit completed after a vacancy is ready inherits its role, but receives no XP or development from the lost veteran.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_T1Z_KERIA','Keria - Genius Support');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_T1Z_KERIA_HELP','Adjacent friendly military units receive +5 HP during otherwise legal normal healing. Keria cannot support himself. The bonus cannot enable healing after forbidden movement/attacks, while embarked or in prohibited terrain. Does not stack with another Keria aura. Permanent ZOFGK role: protection and adaptability.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_T1Z_LEADER','Faker');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_T1Z_LEADER_PEDIA','Lee "Faker" Sang-hyeok became the central figure of SK Telecom T1''s League of Legends legacy after his professional debut in 2013. Celebrated for mechanical precision, leadership, adaptability and calm under pressure, he became known as the Unkillable Demon King.[NEWLINE][NEWLINE]This tribute focuses on the ZOFGK era. Faker led a roster of developing stars through the heartbreak of the 2022 Worlds final, the 2023 championship in Seoul and a successful title defense in London in 2024. His civilization celebrates the trust and discipline of a team, not invulnerability: preserving veterans and training successors remain essential.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_T1Z_NEUTRAL_1','I am listening. What is your plan?');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_T1Z_NOTICE_JOIN','{1_Name} has joined the roster. This unit keeps its own XP and development.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_T1Z_NOTICE_LOST','{1_Name} is vacant. Recruitment takes {2_Num} turns; then produce a new land melee unit in a city with a real T1 Headquarters.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_T1Z_NOTICE_READY','{1_Name} can now be recruited. Produce a new land melee military unit in a city with a real T1 Headquarters. Purchases, gifts and captures do not qualify.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_T1Z_NOTICE_TITLE','ZOFGK - Dynasty Roster');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_T1Z_ONER','Oner - The Initiator');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_T1Z_ONER_HELP','+1 Sight. Double movement through Forest and Jungle using native feature movement; other movement restrictions still apply. Permanent ZOFGK role: jungle pathing, rotations and proactive engagements.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_T1Z_PANEL','ZOFGK Roster');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_T1Z_PANEL_HELP','Protect the five legends. Only distinct roster roles within two hexes count toward Five as One. Development belongs to each individual unit; a successor inherits only its role.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_T1Z_PEACE_1','Let us learn from this contest and prepare for a better future.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_T1Z_PEACE_OFFER_1','Both our peoples have fought hard. There is wisdom in choosing the next battle carefully.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_T1Z_PRESSURE','Demon King Pressure');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_T1Z_PRESSURE_HELP','Temporary -10% Strength while within one hex of an enemy Faker. Removed on movement, death, transfer or peace. Non-stacking; military units only.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_T1Z_SCOUTED','Scouted Talent');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_T1Z_SCOUTED_HELP','+15% experience from combat. Recruit origin marker; retained through genuine upgrades and transfers. Level-ups do not grant Legendary Development.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_T1Z_SHORT','T1');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_T1Z_SLOT_ALIVE','{1_Name}: {2_Unit}[NEWLINE]Development +{3_Num}% / Formation +{4_Num}%');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_T1Z_SLOT_COOLDOWN','{1_Name}: vacant - {2_Num} turns remaining');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_T1Z_SLOT_INITIAL','{1_Name}: awaiting an initial T1 Recruit');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_T1Z_SLOT_READY','{1_Name}: ready - train a land melee unit at Headquarters');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_T1Z_SPY_1','Scout');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_T1Z_SPY_10','Team Manager');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_T1Z_SPY_2','Analyst');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_T1Z_SPY_3','Coach');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_T1Z_SPY_4','Strategist');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_T1Z_SPY_5','Pathfinder');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_T1Z_SPY_6','Observer');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_T1Z_SPY_7','Playmaker');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_T1Z_SPY_8','Academy Mentor');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_T1Z_SPY_9','Draftmaster');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_T1Z_STRATEGY','Domination / Culture. Complexity: 4/5. Develop an Ancient Era core, preserve its experience through upgrades, and fight in a compact formation. Ordinary Recruits also develop, but only five units have legendary roles. Losing a veteran loses its XP and development forever; Headquarters train successors after the cooldown. Siege, ranged support, technology and a sound economy are still essential.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_T1Z_SUPPORT','Keria Support');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_T1Z_SUPPORT_HELP','Temporary +5 HP to otherwise legal normal healing while adjacent to a friendly Keria. Does not heal directly, cannot exceed maximum HP and cannot enable otherwise forbidden healing. Military units only; excludes Keria himself.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_T1Z_SYNERGY_10','Five as One - Three or Four');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_T1Z_SYNERGY_10_HELP','Temporary +10% Strength. At least three distinct living ZOFGK roles, but fewer than five, are within two hexes including this unit. Replaced by the +15% tier when all five are near.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_T1Z_SYNERGY_15','Five as One - Full Roster');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_T1Z_SYNERGY_15_HELP','Temporary +15% Strength. All five distinct living ZOFGK roles are within two hexes including this unit. Replaces the +10% tier; the tiers never stack.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_T1Z_TRADE_1','Agreed. Good preparation benefits both sides.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_T1Z_TRAIT','ZOFGK');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_T1Z_TRAIT_HELP','The first five T1 Recruits become Zeus, Oner, Faker, Gumayusi and Keria, each with a permanent role. Roster units with 3-4 distinct roles within two hexes gain +10% Strength; all five grant +15% instead. Lost roles can be recruited after a speed-scaled 10-turn cooldown by training a new land melee unit in a city with a real T1 Headquarters. Protect your veterans: every genuine Recruit upgrade adds permanent +4% Strength.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_T1Z_UNIT','T1 Recruit');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_T1Z_UNIT_HELP','Replaces Warrior with the active Warrior strength, movement, cost and requirements. Scouted Talent: +15% combat experience, retained through upgrades. Legendary Development: each genuine change of unit type through an upgrade adds +4% permanent Strength. The first five qualifying Recruits receive the five roster roles automatically.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_T1Z_UNIT_PEDIA','Every legend begins as a recruit. T1 scouting identifies potential, but practice, coaching and trust turn it into enduring performance. The Recruit uses the ordinary Warrior model and statistics; its distinction is the history it builds. Genuine upgrades grant permanent strength, never level-ups, healing or promotion purchases.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_T1Z_UNIT_STRATEGY','Train your original roster early. Rotate wounded veterans out of danger and budget Gold for upgrades. A new late-game unit has none of the development of a preserved Ancient Era Recruit. Recruits beyond the original five still receive Scouted Talent and develop through upgrades.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_T1Z_WAR_1','The time for preparation has passed. We will trust our team and commit.');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_T1Z_ZEUS','Zeus - Top Lane Prodigy');
INSERT INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_T1Z_ZEUS_HELP','+15% Strength when attacking cities. No bonus against ordinary units or on defense. Permanent ZOFGK role: top-lane pressure, duelling and decisive split pushes.');
